<template>
  <section class="river-workspace"><header><h2>河网与断面</h2><p>保存常用断面位置，选取成果与洪水后查询流量。</p></header>
    <nav class="tabs"><button v-for="item in tabs" :key="item.id" class="btn" :class="{primary:tab===item.id}" @click="tab=item.id">{{ item.name }}</button></nav>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <div v-if="tab!=='gis'" class="river-layout" :class="{'network-only':tab==='network'}"><RoutingWorkbench v-if="spatial" :spatial="spatial" query-only :queried-point="location?.queried || selected?.definition.queried" visible @point="locate" /><p v-else>正在读取河网…</p>
      <aside v-if="tab==='sections'"><h3>我的断面</h3><select v-model="sectionId" class="input" size="7" aria-label="我的断面"><option v-for="row in sections" :key="row.id" :value="row.id">{{ row.name }}</option></select><p v-if="selected">{{ selected.definition.queried.map(value=>value.toFixed(6)).join('，') }}<template v-if="!selected.compatible"> · 河网已变化，请重新定位</template></p><button v-if="selected && !selected.predefined" class="btn" @click="rename">修改名称</button>
      <p v-if="locating">正在吸附到河道…</p><div v-if="location" class="fields"><p>距点击位置 {{ location.distanceM.toFixed(0) }} 米。保存后可在其他成果中复用。</p><label>断面名称<input v-model.trim="name" class="input" maxlength="80" /></label><button class="btn primary" :disabled="!name || saving" @click="save">保存新断面</button></div>
      <div v-if="selected" class="fields"><h3>查询此断面流量</h3><label>计算成果<select v-model="resultId" class="input" @change="readProcesses"><option value="">选择成果</option><option v-for="row in results" :key="row.id" :value="row.id">{{ row.name || '未命名计算 · '+row.createdAt }}</option></select></label><label>洪水过程<select v-model="processId" class="input"><option value="">选择洪水／连续过程</option><option v-for="row in processes" :key="row.id" :value="row.id">{{ row.name }}</option></select></label><button class="btn primary" :disabled="!resultId || !processId || !selected.compatible" @click="query">查看流量过程</button></div></aside></div>
    <section v-else><button class="btn primary" :disabled="generating" @click="generate">{{ generating?'正在制作图件…':'生成地形河网与汇流分区图' }}</button><p v-if="stage" role="status">{{ stage }}</p><select v-if="spatialTasks.length" v-model="spatialTaskId" class="input" aria-label="已生成图件" @change="readProduct"><option value="">读取已有图件</option><option v-for="row in spatialTasks" :key="row.taskId" :value="row.taskId">{{ row.createdAt }}</option></select><SpatialResults v-if="product" :task-id="spatialTaskId" :product="product" /></section>
  </section>
</template>
<script setup>
import { computed,onMounted,onBeforeUnmount,ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { modelApi,uniqueRequestId } from '@/services/modelBackendService'
import RoutingWorkbench from '@/components/model/RoutingWorkbench.vue'
import SpatialResults from '@/components/model/SpatialResults.vue'
const router=useRouter(),tab=ref('network'),spatial=ref(null),error=ref(''),sections=ref([]),sectionId=ref(''),location=ref(null),point=ref(null),name=ref(''),saving=ref(false),locating=ref(false)
const results=ref([]),resultId=ref(''),processes=ref([]),processId=ref(''),spatialTasks=ref([]),spatialTaskId=ref(''),product=ref(null),generating=ref(false),stage=ref('')
const tabs=[{id:'network',name:'河网查看'},{id:'sections',name:'我的断面'},{id:'gis',name:'GIS图件'}]
const selected=computed(()=>sections.value.find(row=>row.id===sectionId.value))
let disposed=false,locationToken=0,processToken=0
onBeforeUnmount(()=>{disposed=true;locationToken++;processToken++})
async function locate(coordinates){if(tab.value!=='sections')return;const token=++locationToken;point.value={lon:coordinates[0],lat:coordinates[1]};location.value=null;locating.value=true;error.value='';try{const row=await modelApi('river-sections/locate',{method:'POST',body:{projectId:'nananxi-xufan',point:point.value},timeoutMs:60000});if(token===locationToken)location.value=row}catch(failure){if(token===locationToken)error.value=failure.message}finally{if(token===locationToken)locating.value=false}}
async function save(){saving.value=true;try{const row=await modelApi('river-sections',{method:'POST',body:{name:name.value,projectId:'nananxi-xufan',point:point.value},timeoutMs:60000});sections.value.unshift(row);sectionId.value=row.id;name.value='';location.value=null}catch(failure){error.value=failure.message}finally{saving.value=false}}
async function rename(){try{const row=selected.value;const {value}=await ElMessageBox.prompt('填写断面名称','修改名称',{inputValue:row.name,inputValidator:value=>Boolean(value?.trim())&&value.trim().length<=80});const saved=await modelApi('river-sections/'+row.id+'/rename',{method:'POST',body:{name:value.trim(),revision:row.revision}});Object.assign(row,saved)}catch(failure){if(failure instanceof Error)error.value=failure.message}}
async function readProcesses(){const token=++processToken;processes.value=[];processId.value='';if(!resultId.value)return;try{const row=await modelApi('result-catalog/'+resultId.value+'/processes',{timeoutMs:60000});if(token!==processToken)return;processes.value=row.processes;processId.value=row.processes.length===1?row.processes[0].id:''}catch(failure){if(token===processToken)error.value=failure.message}}
function query(){router.push({path:'/results/'+resultId.value+'/sections',query:{process:processId.value,section:sectionId.value}})}
async function readProduct(){product.value=null;if(!spatialTaskId.value)return;try{const row=await modelApi('tasks/'+spatialTaskId.value+'/result',{timeoutMs:60000});product.value=row.spatial||row.spatialProduct||row.spatialProducts||row}catch(failure){error.value=failure.message}}
async function loadTasks(){const payload=await modelApi('tasks');spatialTasks.value=(payload.tasks||[]).filter(row=>row.runConfig?.runType==='spatialExport'&&['completed','archived'].includes(row.status))}
async function generate(){generating.value=true;error.value='';try{let task=await modelApi('tasks',{method:'POST',body:{requestId:uniqueRequestId('SPATIAL'),runType:'spatialExport',inputs:{bundleVersionId:'HISTORICAL_SPATIAL_V1'}}});while(['queued','running'].includes(task.status)){if(disposed)return;stage.value=task.stageLabel||'正在制作图件';await new Promise(resolve=>setTimeout(resolve,1000));task=await modelApi('tasks/'+task.taskId)}if(disposed)return;if(task.status!=='completed')throw new Error(task.errorMessage||'图件生成未完成');spatialTaskId.value=task.taskId;await readProduct();await loadTasks();stage.value='图件已保存'}catch(failure){error.value=failure.message}finally{generating.value=false}}
onMounted(async()=>{const jobs=[['河网',()=>modelApi('spatial-products?bundleVersionId=HISTORICAL_SPATIAL_V1',{timeoutMs:60000}),row=>spatial.value=row],['断面',()=>modelApi('river-sections'),row=>{sections.value=row.sections;sectionId.value=row.sections[0]?.id||''}],['成果',()=>modelApi('result-catalog',{timeoutMs:60000}),row=>results.value=row.results||[]],['图件',loadTasks,()=>{}]];await Promise.allSettled(jobs.map(async([label,read,apply])=>{try{const row=await read();if(!disposed)apply(row)}catch(failure){error.value+=(error.value?'；':'')+label+'：'+failure.message}}))})
</script>
<style scoped>
.river-layout.network-only{grid-template-columns:minmax(0,1fr)}
.river-workspace{font-size:14px;color:#345e54}.river-workspace h2{font-size:22px}.river-workspace p{line-height:1.7;color:#71867e}.tabs{display:flex;gap:12px;margin:20px 0}.river-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:24px}.river-layout>aside{display:grid;gap:14px;align-content:start}.fields{display:grid;gap:12px;padding-top:18px;border-top:1px solid #dce7e2}.fields label{display:grid;gap:8px}.error{color:#a63c2f!important}.river-workspace :is(.btn,.input){font-size:14px;min-height:36px}.river-workspace select{width:100%}.river-layout :deep(.routing-layout){grid-template-columns:1fr}@media(max-width:1100px){.river-layout{grid-template-columns:1fr}}
</style>
